// =============================================================================
// Appendix A — chat-agents-contract-typing
//
// New DTOs introduced by OpenSpec change `deck-go-chat-agents-contract-typing`.
// Appended at file end to preserve prompt-cache prefix byte-stability of the
// existing contract surface (per design.md Risks table + tasks.md 2.8).
// =============================================================================

// -- SSE event payloads -------------------------------------------------------

// 来自 deck-go/frontend/src/components/panels/agents/useAgentMetricsSSE.ts:77
// Activity event — agents panel metrics stream. Envelope carries arbitrary
// upstream fields beyond `agentId`/`type`; index signature keeps the surface
// open without forcing every consumer to update on upstream additions.
export interface DeckGoActivityStreamEvent {
  agentId: string;
  type: string;
  [key: string]: unknown;
}

// 来自 deck-go/frontend/src/components/panels/agents/useAgentMetricsSSE.ts:85
// agent.status.changed — current upstream values are `"busy"` and `"idle"`;
// `(string & {})` extension keeps type-checking strict on known values while
// tolerating new upstream values without a contract change.
export interface DeckGoAgentStatusChangedStreamEvent {
  agentId: string;
  status: "busy" | "idle" | (string & {});
}

// -- Approval request mirror -------------------------------------------------

// 来自 src/infra/exec-approvals.ts:61-67 (SystemRunApprovalBinding upstream)
export interface DeckGoSystemRunApprovalBinding {
  argv: string[];
  cwd: string | null;
  agentId: string | null;
  sessionKey: string | null;
  envHash: string | null;
}

// 来自 src/infra/exec-approvals.ts:69-73 (SystemRunApprovalFileOperand upstream)
export interface DeckGoSystemRunApprovalFileOperand {
  argvIndex: number;
  path: string;
  sha256: string;
}

// 来自 src/infra/exec-approvals.ts:75-83 (SystemRunApprovalPlan upstream)
export interface DeckGoSystemRunApprovalPlan {
  argv: string[];
  cwd: string | null;
  commandText: string;
  commandPreview?: string | null;
  agentId: string | null;
  sessionKey: string | null;
  mutableFileOperand?: DeckGoSystemRunApprovalFileOperand | null;
}

// 来自 src/infra/exec-approvals.ts:85-106 (ExecApprovalRequestPayload upstream)
export interface DeckGoApprovalRequestPayload {
  command: string;
  commandPreview?: string | null;
  commandArgv?: string[];
  // UI-safe env-key preview displayed in approval prompts.
  envKeys?: string[];
  systemRunBinding?: DeckGoSystemRunApprovalBinding | null;
  systemRunPlan?: DeckGoSystemRunApprovalPlan | null;
  cwd?: string | null;
  nodeId?: string | null;
  host?: string | null;
  security?: string | null;
  ask?: string | null;
  // Upstream `ExecApprovalDecision` is a closed string union; widen to plain
  // string here to avoid coupling to an upstream-only type. (`readonly`
  // modifier dropped — codegen does not understand it; on-the-wire JSON is
  // a regular array so this is a documentation-only relaxation.)
  allowedDecisions?: string[];
  agentId?: string | null;
  resolvedPath?: string | null;
  sessionKey?: string | null;
  turnSourceChannel?: string | null;
  turnSourceTo?: string | null;
  turnSourceAccountId?: string | null;
  turnSourceThreadId?: string | number | null;
}

// 来自 src/infra/exec-approvals.ts:108-113 (ExecApprovalRequest upstream).
// Carried through `chat_snapshot.go:42` as `activeApproval`; deck-go is a
// transparent pass-through forwarder, so the wire shape == upstream shape.
export interface DeckGoApprovalRequest {
  id: string;
  request: DeckGoApprovalRequestPayload;
  createdAtMs: number;
  expiresAtMs: number;
}

// -- Chat write request DTOs --------------------------------------------------

// 来自 deck-go/backend/internal/server/chat.go:122 (POST /chat/sessions/reset)
export interface DeckGoChatSessionResetRequest {
  sessionKey: string;
  reason?: string;
}

// 来自 deck-go/backend/internal/server/chat.go:149 (POST /chat/sessions/clear)
export interface DeckGoChatSessionClearRequest {
  sessionKey: string;
}

// 来自 deck-go/backend/internal/server/chat.go:54 (DELETE /chat/sessions)
// Backend reads only `sessionKey`; `agentId` is forwarded by current frontend
// call sites but silently dropped. Kept on the DTO to reflect the on-the-wire
// shape until the call site is migrated.
export interface DeckGoChatSessionDeleteRequest {
  sessionKey: string;
  agentId?: string | null;
}

// 来自 deck-go/backend/internal/server/chat.go:171 (POST /chat/sessions/patch)
// Backend decodes body as `map[string]any` and forwards to upstream
// `sessions.patch` flat (no `extension` wrapping on the wire). Known patch
// fields are typed here for autocomplete + safety; the open index signature
// preserves forward-compat for upstream additions until the contract is
// extended.
export interface DeckGoChatSessionPatchRequest {
  sessionKey: string;
  // Session view metadata edits.
  title?: string;
  label?: string | null;
  archived?: boolean;
  pinned?: boolean;
  // Per-session model controls (chat slash commands write these).
  thinkingLevel?: string | null;
  fastMode?: boolean | null;
  verboseLevel?: string | null;
  reasoningLevel?: string | null;
  responseUsage?: string | null;
  sendPolicy?: string | null;
  // Forward-compatible: backend transparently forwards unknown keys.
  [key: string]: unknown;
}

// 来自 deck-go/backend/internal/server/chat.go:302 (POST /chat/compact)
export interface DeckGoChatCompactRequest {
  sessionKey: string;
}

// 来自 deck-go/backend/internal/server/chat.go:396 (POST /chat/projection)
// Handler is presently a noop (returns `{ok:true}` after sessionKey decode);
// behavior fix lives in follow-up `deck-go-chat-projection-handler-fix`.
// `a2uiState` is forwarded by current frontend call sites (chat-canvas
// projection persistence) and dropped server-side; it stays on the DTO to
// reflect the on-the-wire shape until the handler-fix follow-up tightens it.
export interface DeckGoChatProjectionRequest {
  sessionKey: string;
  a2uiState?: Record<string, unknown> | null;
}

// 来自 deck-go/backend/internal/server/chat.go:322 (POST /chat/compaction)
// Action-discriminated request — list / branch / restore.
export type DeckGoChatCompactionRequest =
  | { action: "list"; key: string }
  | { action: "branch"; key: string; checkpointId: string }
  | { action: "restore"; key: string; checkpointId: string };

// 来自 deck-go/backend/internal/server/assets.go:202 (POST /deck/canvas, action: ready|unready)
export interface DeckGoCanvasBridgeReadyRequest {
  action: "ready" | "unready";
  sessionKey: string;
}

// 来自 deck-go/backend/internal/server/assets.go:202 (POST /deck/canvas, action: resolve)
// `result` carries plugin-defined JS evaluation output; intentionally
// `unknown` because canvas hosts emit different shapes.
export interface DeckGoCanvasBridgeEvalRequest {
  action: "resolve";
  evalId: string;
  result: unknown;
}

// -- Agents BFF write DTOs ----------------------------------------------------

// 来自 deck-go/backend/internal/server/inventory.go:23 (POST /agents)
// Backend reads exactly these 4 fields and discards the rest. `name` is
// mandatory; `workspace` falls back to a server-resolved default when blank.
export interface DeckGoAgentCreateRequest {
  name: string;
  workspace?: string;
  emoji?: string;
  avatar?: string;
}

// 来自 deck-go/backend/internal/server/inventory.go:117 (PATCH /agents/{agentId})
// Body is forwarded to upstream `agents.update`; mirror upstream
// `AgentsUpdateParamsSchema` (src/gateway/protocol/schema/agents-models-skills.ts:80-91)
// minus `agentId`, which is supplied via the URL path.
export interface DeckGoAgentPatchRequest {
  name?: string;
  workspace?: string;
  model?: string;
  emoji?: string;
  avatar?: string;
}
